const raw = $input.first().json;
const object = v => v && typeof v === 'object' && !Array.isArray(v) ? v : {};
const event = object(raw), parent = object(event.workflow), execution = object(event.execution), trigger = object(event.trigger);
const own = typeof $workflow === 'object' ? $workflow : {};
const self = parent.name === 'oke-errors' || Boolean(own.id && (typeof parent.id === 'string' || Number.isSafeInteger(parent.id)) && String(parent.id) === String(own.id));
const workflowNames = ['oke-support', 'oke-index', 'oke-search', 'oke-handoff'];
const source_workflow = workflowNames.includes(parent.name) ? parent.name : 'unknown';
const knownNodes = ["E02 Safe Error Context", "E03 Store Alert App", "E03 Store Alert Practice", "E04 Store DLQ App", "E04 Store DLQ Practice", "E05 Outcome", "H01 Handoff Webhook", "H02 Validate and Map", "H02a Valid Input", "H03 Select Store", "H03a Store Ready", "H03b App Ticket Store", "H04 Create Ticket App", "H04 Create Ticket Practice", "H04 Retry Ticket App", "H04 Retry Ticket Practice", "H05 Recheck Budget", "H05 Restore First Result", "H05 Retry Gate", "H05 Wait", "H05a Retry Allowed", "H05b App Retry Store", "H05c Retry Still Allowed", "H06 Keep Ticket", "H07 Failure Context", "H08 Check Alert", "H08 Store Alert App", "H08 Store Alert Practice", "H08a App Alert Store", "H09 Check DLQ", "H09 Store DLQ App", "H09 Store DLQ Practice", "H09a Needs DLQ", "H09b App DLQ Store", "H10 Build Result", "H11 Respond", "N09 Search knowledge", "N13 Writer Agent", "N14 Verifier Agent", "N20 Map handoff", "N20 Mock C04", "N20 Prepare handoff", "N22 Finalize P0-3", "N22 Output filter"];
const nodeName = execution.lastNodeExecuted ?? object(object(execution.error).node).name ?? object(object(trigger.error).node).name;
const source_node = knownNodes.includes(nodeName) ? nodeName : 'unknown';
const id = typeof execution.id === 'string' ? execution.id
  : Number.isSafeInteger(execution.id) && execution.id > 0 ? String(execution.id) : '';
const execution_ref = /^\d{1,20}$/.test(id) ? id : null;
const error_kind = Object.keys(object(trigger.error)).length ? 'trigger_error'
  : Object.keys(object(execution.error)).length ? 'execution_error' : 'unknown';
// Standard Error Trigger data does not prove an inquiry ID. Never infer it from raw error/context/URL.
return [{ json: { skip: self, request_id: null, execution_ref, source_workflow, source_node, error_kind } }];

const safe = $input.first().json;
const unavailable = () => [{ json: { ...safe, configuration_error: true, ready: false, alerted: false, dlq: false } }];
try {
  const mode = $env.SERVICE_MODE;
  if (!['practice', 'app'].includes(mode)) return unavailable();
  const value = mode === 'app' ? ($env.WONMIN_APP_STORE_URL || 'http://backend:8000')
    : ($env.WONMIN_PRACTICE_STORE_URL || 'http://data-api:8800');
  const match = typeof value === 'string' && /^(https?:\/\/[a-zA-Z0-9.-]+)(?::([0-9]{1,5}))?\/?$/.exec(value);
  if (!match || (match[2] && (Number(match[2]) < 1 || Number(match[2]) > 65535))) return unavailable();
  const base_url = match[1] + (match[2] ? ':' + match[2] : '');
  const alert_payload = { workflow: 'oke-errors', node: 'E02 Safe Error Context',
    message: '예상 밖 워크플로우 오류 (' + safe.source_workflow + '/' + safe.source_node
      + '). 부모 실행: ' + (safe.execution_ref ?? '미상'), severity: 'high' };
  if (mode === 'app' && safe.execution_ref) alert_payload.event_key = 'n8n-execution:' + safe.execution_ref + ':unexpected-error';
  const dlq_payload = { request_id: null, workflow: 'oke-errors', node: 'E02 Safe Error Context',
    reason: 'unexpected', safe_payload: { stage: 'unexpected', source_workflow: safe.source_workflow,
      source_node: safe.source_node, error_kind: safe.error_kind } };
  if (safe.execution_ref) dlq_payload.execution_ref = safe.execution_ref;
  return [{ json: { ...safe, ready: true, mode, base_url, alert_payload, dlq_payload } }];
} catch { return unavailable(); }

const state = $('E02 Select Store').first().json;
const reply = $input.first().json, b = reply.body;
const validCount = b && Number.isSafeInteger(b.count) && b.count >= 1;
const ack = validCount && ((b.stored === 1 && b.duplicate !== true)
  || (state.mode === 'app' && b.stored === 0 && b.duplicate === true));
const alerted = Boolean(reply.statusCode === 200 && ack);
const { alert_payload, ...safe } = state;
// Never rethrow sink errors. Always proceed to independent DLQ attempt.
return [{ json: { ...safe, alerted, dlq: false } }];

const state = $('E03 Check Alert').first().json;
const reply = $input.first().json, b = reply.body;
const dlq = Boolean(reply.statusCode === 200 && b && b.stored === 1
  && Number.isSafeInteger(b.count) && b.count >= 1);
return [{ json: { request_id: null, execution_ref: state.execution_ref, source_workflow: state.source_workflow,
  source_node: state.source_node, error_kind: state.error_kind, alerted: state.alerted, dlq } }];

const state = $input.first().json;
const alerted = state.alerted === true, dlq = state.dlq === true;
const outcome = state.skip ? 'skipped_self' : state.configuration_error ? 'configuration_error'
  : alerted && dlq ? 'success' : alerted || dlq ? 'partial_failure' : 'failed';
// Internal outcome only: never manufacture an HTTP response for the already-failed parent.
return [{ json: { workflow: 'oke-errors', outcome, request_id: null, execution_ref: state.execution_ref ?? null,
  source_workflow: state.source_workflow ?? 'unknown', source_node: state.source_node ?? 'unknown',
  error_kind: state.error_kind ?? 'unknown', alerted, dlq } }];
